17	package org.springframework.boot.context.properties.source;
18	
19	import java.util.ArrayList;
20	import java.util.Collection;
21	import java.util.Collections;
22	import java.util.List;
23	import java.util.Locale;
24	import java.util.Map;
25	import java.util.function.Function;
26	import java.util.function.IntFunction;
27	
28	import org.jspecify.annotations.Nullable;
29	
30	import org.springframework.lang.Contract;
31	import org.springframework.util.Assert;
32	import org.springframework.util.StringUtils;
33	
34	/**
35	 * A configuration property name composed of elements separated by dots. User created
36	 * names may contain the characters "{@code a-z}" "{@code 0-9}" and "{@code -}", they must
37	 * be lower-case and must start with an alphanumeric character. The "{@code -}" is used
38	 * purely for formatting, i.e. "{@code foo-bar}" and "{@code foobar}" are considered
39	 * equivalent.
40	 * <p>
41	 * The "{@code [}" and "{@code ]}" characters may be used to indicate an associative
42	 * index(i.e. a {@link Map} key or a {@link Collection} index). Indexes names are not
43	 * restricted and are considered case-sensitive.
44	 * <p>
45	 * Here are some typical examples:
46	 * <ul>
47	 * <li>{@code spring.main.banner-mode}</li>
48	 * <li>{@code server.hosts[0].name}</li>
49	 * <li>{@code log[org.springboot].level}</li>
50	 * </ul>
51	 *
52	 * @author Phillip Webb
53	 * @author Madhura Bhave
54	 * @since 2.0.0
55	 * @see #of(CharSequence)
56	 * @see ConfigurationPropertySource
57	 */
58	public final class ConfigurationPropertyName implements Comparable<ConfigurationPropertyName> {
59	
60		private static final String EMPTY_STRING = "";
61	
62		/**
63		 * An empty {@link ConfigurationPropertyName}.
64		 */
65		public static final ConfigurationPropertyName EMPTY = new ConfigurationPropertyName(Elements.EMPTY);
66	
67		private final Elements elements;
68	
69		private final @Nullable CharSequence[] uniformElements;
70	
71		private int hashCode;
72	
73		private @Nullable String[] string = new String[ToStringFormat.values().length];
74	
75		private @Nullable Boolean hasDashedElement;
76	
77		private @Nullable ConfigurationPropertyName systemEnvironmentLegacyName;
78	
79		private ConfigurationPropertyName(Elements elements) {
80			this.elements = elements;
81			this.uniformElements = new CharSequence[elements.getSize()];
82		}
83	
84		/**
85		 * Returns {@code true} if this {@link ConfigurationPropertyName} is empty.
86		 * @return {@code true} if the name is empty
87		 */
88		public boolean isEmpty() {
89			return this.elements.getSize() == 0;
90		}
91	
92		/**
93		 * Return if the last element in the name is indexed.
94		 * @return {@code true} if the last element is indexed
95		 */
96		public boolean isLastElementIndexed() {
97			int size = getNumberOfElements();
98			return (size > 0 && isIndexed(size - 1));
99		}
100	
101		/**
102		 * Return {@code true} if any element in the name is indexed.
103		 * @return if the element has one or more indexed elements
104		 * @since 2.2.10
105		 */
106		public boolean hasIndexedElement() {
107			for (int i = 0; i < getNumberOfElements(); i++) {
108				if (isIndexed(i)) {
109					return true;
110				}
111			}
112			return false;
113		}
114	
115		/**
116		 * Return if the element in the name is indexed.
117		 * @param elementIndex the index of the element
118		 * @return {@code true} if the element is indexed
119		 */
120		boolean isIndexed(int elementIndex) {
121			return this.elements.getType(elementIndex).isIndexed();
122		}
123	
124		/**
125		 * Return if the element in the name is indexed and numeric.
126		 * @param elementIndex the index of the element
127		 * @return {@code true} if the element is indexed and numeric
128		 */
129		public boolean isNumericIndex(int elementIndex) {
130			return this.elements.getType(elementIndex) == ElementType.NUMERICALLY_INDEXED;
131		}
132	
133		/**
134		 * Return the last element in the name in the given form.
135		 * @param form the form to return
136		 * @return the last element
137		 */
138		public String getLastElement(Form form) {
139			int size = getNumberOfElements();
140			return (size != 0) ? getElement(size - 1, form) : EMPTY_STRING;
141		}
142	
143		/**
144		 * Return an element in the name in the given form.
145		 * @param elementIndex the element index
146		 * @param form the form to return
147		 * @return the last element
148		 */
149		public String getElement(int elementIndex, Form form) {
150			CharSequence element = this.elements.get(elementIndex);
151			ElementType type = this.elements.getType(elementIndex);
152			if (type.isIndexed()) {
153				return element.toString();
154			}
155			if (form == Form.ORIGINAL) {
156				if (type != ElementType.NON_UNIFORM) {
157					return element.toString();
158				}
159				return convertToOriginalForm(element).toString();
160			}
161			if (form == Form.DASHED) {
162				if (type == ElementType.UNIFORM || type == ElementType.DASHED) {
163					return element.toString();
164				}
165				return convertToDashedElement(element).toString();
166			}
167			CharSequence uniformElement = this.uniformElements[elementIndex];
168			if (uniformElement == null) {
169				uniformElement = (type != ElementType.UNIFORM) ? convertToUniformElement(element) : element;
170				this.uniformElements[elementIndex] = uniformElement.toString();
171			}
172			return uniformElement.toString();
173		}
174	
175		private CharSequence convertToOriginalForm(CharSequence element) {
176			return convertElement(element, false,
177					(ch, i) -> ch == '_' || ElementsParser.isValidChar(Character.toLowerCase(ch), i));
178		}
179	
180		private CharSequence convertToDashedElement(CharSequence element) {
181			return convertElement(element, true, ElementsParser::isValidChar);
182		}
183	
184		private CharSequence convertToUniformElement(CharSequence element) {
185			return convertElement(element, true, (ch, i) -> ElementsParser.isAlphaNumeric(ch));
186		}
187	
188		private CharSequence convertElement(CharSequence element, boolean lowercase, ElementCharPredicate filter) {
189			StringBuilder result = new StringBuilder(element.length());
190			for (int i = 0; i < element.length(); i++) {
191				char ch = lowercase ? Character.toLowerCase(element.charAt(i)) : element.charAt(i);
192				if (filter.test(ch, i)) {
193					result.append(ch);
194				}
195			}
196			return result;
197		}
198	
199		/**
200		 * Return the total number of elements in the name.
201		 * @return the number of elements
202		 */
203		public int getNumberOfElements() {
204			return this.elements.getSize();
205		}
206	
207		/**
208		 * Create a new {@link ConfigurationPropertyName} by appending the given suffix.
209		 * @param suffix the elements to append
210		 * @return a new {@link ConfigurationPropertyName}
211		 * @throws InvalidConfigurationPropertyNameException if the result is not valid
212		 */
213		public ConfigurationPropertyName append(@Nullable String suffix) {
214			if (!StringUtils.hasLength(suffix)) {
215				return this;
216			}
217			Elements additionalElements = probablySingleElementOf(suffix);
218			return new ConfigurationPropertyName(this.elements.append(additionalElements));
219		}
220	
221		/**
222		 * Create a new {@link ConfigurationPropertyName} by appending the given suffix.
223		 * @param suffix the elements to append
224		 * @return a new {@link ConfigurationPropertyName}
225		 * @since 2.5.0
226		 */
227		public ConfigurationPropertyName append(@Nullable ConfigurationPropertyName suffix) {
228			if (suffix == null) {
229				return this;
230			}
231			return new ConfigurationPropertyName(this.elements.append(suffix.elements));
232		}
233	
234		/**
235		 * Return the parent of this {@link ConfigurationPropertyName} or
236		 * {@link ConfigurationPropertyName#EMPTY} if there is no parent.
237		 * @return the parent name
238		 */
239		public ConfigurationPropertyName getParent() {
240			int numberOfElements = getNumberOfElements();
241			return (numberOfElements <= 1) ? EMPTY : chop(numberOfElements - 1);
242		}
243	
244		/**
245		 * Return a new {@link ConfigurationPropertyName} by chopping this name to the given
246		 * {@code size}. For example, {@code chop(1)} on the name {@code foo.bar} will return
247		 * {@code foo}.
248		 * @param size the size to chop
249		 * @return the chopped name
250		 */
251		public ConfigurationPropertyName chop(int size) {
252			if (size >= getNumberOfElements()) {
253				return this;
254			}
255			return new ConfigurationPropertyName(this.elements.chop(size));
256		}
257	
258		/**
259		 * Return a new {@link ConfigurationPropertyName} by based on this name offset by
260		 * specific element index. For example, {@code subName(1)} on the name {@code foo.bar}
261		 * will return {@code bar}.
262		 * @param offset the element offset
263		 * @return the sub name
264		 * @since 2.5.0
265		 */
266		public ConfigurationPropertyName subName(int offset) {
267			if (offset == 0) {
268				return this;
269			}
270			if (offset == getNumberOfElements()) {
271				return EMPTY;
272			}
273			if (offset < 0 || offset > getNumberOfElements()) {
274				throw new IndexOutOfBoundsException("Offset: " + offset + ", NumberOfElements: " + getNumberOfElements());
275			}
276			return new ConfigurationPropertyName(this.elements.subElements(offset));
277		}
278	
279		/**
280		 * Returns {@code true} if this element is an immediate parent of the specified name.
281		 * @param name the name to check
282		 * @return {@code true} if this name is an ancestor
283		 */
284		public boolean isParentOf(ConfigurationPropertyName name) {
285			Assert.notNull(name, "'name' must not be null");
286			if (getNumberOfElements() != name.getNumberOfElements() - 1) {
287				return false;
288			}
289			return isAncestorOf(name);
290		}
291	
292		/**
293		 * Returns {@code true} if this element is an ancestor (immediate or nested parent) of
294		 * the specified name.
295		 * @param name the name to check
296		 * @return {@code true} if this name is an ancestor
297		 */
298		public boolean isAncestorOf(ConfigurationPropertyName name) {
299			Assert.notNull(name, "'name' must not be null");
300			if (getNumberOfElements() >= name.getNumberOfElements()) {
301				return false;
302			}
303			return endsWithElementsEqualTo(name);
304		}
305	
306		@Override
307		public int compareTo(ConfigurationPropertyName other) {
308			return compare(this, other);
309		}
310	
311		private int compare(ConfigurationPropertyName n1, ConfigurationPropertyName n2) {
312			int l1 = n1.getNumberOfElements();
313			int l2 = n2.getNumberOfElements();
314			int i1 = 0;
315			int i2 = 0;
316			while (i1 < l1 || i2 < l2) {
317				try {
318					ElementType type1 = (i1 < l1) ? n1.elements.getType(i1) : null;
319					ElementType type2 = (i2 < l2) ? n2.elements.getType(i2) : null;
320					String e1 = (i1 < l1) ? n1.getElement(i1++, Form.UNIFORM) : null;
321					String e2 = (i2 < l2) ? n2.getElement(i2++, Form.UNIFORM) : null;
322					int result = compare(e1, type1, e2, type2);
323					if (result != 0) {
324						return result;
325					}
326				}
327				catch (ArrayIndexOutOfBoundsException ex) {
328					throw new RuntimeException(ex);
329				}
330			}
331			return 0;
332		}
333	
334		private int compare(@Nullable String e1, @Nullable ElementType type1, @Nullable String e2,
335				@Nullable ElementType type2) {
336			if (e1 == null) {
337				return -1;
338			}
339			if (e2 == null) {
340				return 1;
341			}
342			Assert.state(type1 != null, "'type1' must not be null");
343			Assert.state(type2 != null, "'type2' must not be null");
344			int result = Boolean.compare(type2.isIndexed(), type1.isIndexed());
345			if (result != 0) {
346				return result;
347			}
348			if (type1 == ElementType.NUMERICALLY_INDEXED && type2 == ElementType.NUMERICALLY_INDEXED) {
349				long v1 = Long.parseLong(e1);
350				long v2 = Long.parseLong(e2);
351				return Long.compare(v1, v2);
352			}
353			return e1.compareTo(e2);
354		}
355	
356		@Override
357		public boolean equals(Object obj) {
358			if (obj == this) {
359				return true;
360			}
361			if (obj == null || obj.getClass() != getClass()) {
362				return false;
363			}
364			ConfigurationPropertyName other = (ConfigurationPropertyName) obj;
365			if (getNumberOfElements() != other.getNumberOfElements()) {
366				return false;
367			}
368			if (this.elements.canShortcutWithSource(ElementType.UNIFORM)
369					&& other.elements.canShortcutWithSource(ElementType.UNIFORM)) {
370				return toString().equals(other.toString());
371			}
372			if (hashCode() != other.hashCode()) {
373				return false;
374			}
375			if (toStringMatches(toString(), other.toString())) {
376				return true;
377			}
378			return endsWithElementsEqualTo(other);
379		}
380	
381		private boolean toStringMatches(String s1, String s2) {
382			return s1.hashCode() == s2.hashCode() && s1.equals(s2);
383		}
384	
385		private boolean endsWithElementsEqualTo(ConfigurationPropertyName name) {
386			for (int i = this.elements.getSize() - 1; i >= 0; i--) {
387				if (elementDiffers(this.elements, name.elements, i)) {
388					return false;
389				}
390			}
391			return true;
392		}
393	
394		private boolean elementDiffers(Elements e1, Elements e2, int i) {
395			ElementType type1 = e1.getType(i);
396			ElementType type2 = e2.getType(i);
397			if (type1.allowsFastEqualityCheck() && type2.allowsFastEqualityCheck()) {
398				return !fastElementEquals(e1, e2, i);
399			}
400			if (type1.allowsDashIgnoringEqualityCheck() && type2.allowsDashIgnoringEqualityCheck()) {
401				return !dashIgnoringElementEquals(e1, e2, i);
402			}
403			return !defaultElementEquals(e1, e2, i);
404		}
405	
406		private boolean fastElementEquals(Elements e1, Elements e2, int i) {
407			int length1 = e1.getLength(i);
408			int length2 = e2.getLength(i);
409			if (length1 == length2) {
410				int i1 = 0;
411				while (length1-- != 0) {
412					char ch1 = e1.charAt(i, i1);
413					char ch2 = e2.charAt(i, i1);
414					if (ch1 != ch2) {
415						return false;
416					}
417					i1++;
418				}
419				return true;
420			}
421			return false;
422		}
423	
424		private boolean dashIgnoringElementEquals(Elements e1, Elements e2, int i) {
425			int l1 = e1.getLength(i);
426			int l2 = e2.getLength(i);
427			int i1 = 0;
428			int i2 = 0;
429			while (i1 < l1) {
430				if (i2 >= l2) {
431					return remainderIsDashes(e1, i, i1);
432				}
433				char ch1 = e1.charAt(i, i1);
434				char ch2 = e2.charAt(i, i2);
435				if (ch1 == '-') {
436					i1++;
437				}
438				else if (ch2 == '-') {
439					i2++;
440				}
441				else if (ch1 != ch2) {
442					return false;
443				}
444				else {
445					i1++;
446					i2++;
447				}
448			}
449			if (i2 < l2) {
450				if (e2.getType(i).isIndexed()) {
451					return false;
452				}
453				do {
454					char ch2 = e2.charAt(i, i2++);
455					if (ch2 != '-') {
456						return false;
457					}
458				}
459				while (i2 < l2);
460			}
461			return true;
462		}
463	
464		private boolean defaultElementEquals(Elements e1, Elements e2, int i) {
465			int l1 = e1.getLength(i);
466			int l2 = e2.getLength(i);
467			boolean indexed1 = e1.getType(i).isIndexed();
468			boolean indexed2 = e2.getType(i).isIndexed();
469			int i1 = 0;
470			int i2 = 0;
471			while (i1 < l1) {
472				if (i2 >= l2) {
473					return remainderIsNotAlphanumeric(e1, i, i1);
474				}
475				char ch1 = indexed1 ? e1.charAt(i, i1) : Character.toLowerCase(e1.charAt(i, i1));
476				char ch2 = indexed2 ? e2.charAt(i, i2) : Character.toLowerCase(e2.charAt(i, i2));
477				if (!indexed1 && !ElementsParser.isAlphaNumeric(ch1)) {
478					i1++;
479				}
480				else if (!indexed2 && !ElementsParser.isAlphaNumeric(ch2)) {
481					i2++;
482				}
483				else if (ch1 != ch2) {
484					return false;
485				}
486				else {
487					i1++;
488					i2++;
489				}
490			}
491			if (i2 < l2) {
492				return remainderIsNotAlphanumeric(e2, i, i2);
493			}
494			return true;
495		}
496	
497		private boolean remainderIsNotAlphanumeric(Elements elements, int element, int index) {
498			if (elements.getType(element).isIndexed()) {
499				return false;
500			}
501			int length = elements.getLength(element);
502			do {
503				char c = Character.toLowerCase(elements.charAt(element, index++));
504				if (ElementsParser.isAlphaNumeric(c)) {
505					return false;
506				}
507			}
508			while (index < length);
509			return true;
510		}
511	
512		private boolean remainderIsDashes(Elements elements, int element, int index) {
513			if (elements.getType(element).isIndexed()) {
514				return false;
515			}
516			int length = elements.getLength(element);
517			do {
518				char c = elements.charAt(element, index++);
519				if (c != '-') {
520					return false;
521				}
522			}
523			while (index < length);
524			return true;
525		}
526	
527		@Override
528		public int hashCode() {
529			int hashCode = this.hashCode;
530			Elements elements = this.elements;
531			if (hashCode == 0 && elements.getSize() != 0) {
532				for (int elementIndex = 0; elementIndex < elements.getSize(); elementIndex++) {
533					hashCode = 31 * hashCode + elements.hashCode(elementIndex);
534				}
535				this.hashCode = hashCode;
536			}
537			return hashCode;
538		}
539	
540		@Nullable ConfigurationPropertyName asSystemEnvironmentLegacyName() {
541			ConfigurationPropertyName name = this.systemEnvironmentLegacyName;
542			if (name == null) {
543				name = ConfigurationPropertyName
544					.ofIfValid(buildSimpleToString('.', (i) -> getElement(i, Form.DASHED).replace('-', '.')));
545				this.systemEnvironmentLegacyName = (name != null) ? name : EMPTY;
546			}
547			return (name != EMPTY) ? name : null;
548		}
549	
550		@Override
551		public String toString() {
552			return toString(ToStringFormat.DEFAULT, false);
553		}
554	
555		String toString(ToStringFormat format, boolean upperCase) {
556			String string = this.string[format.ordinal()];
557			if (string == null) {
558				string = buildToString(format);
559				this.string[format.ordinal()] = string;
560			}
561			return (!upperCase) ? string : string.toUpperCase(Locale.ENGLISH);
562		}
563	
564		private String buildToString(ToStringFormat format) {
565			return switch (format) {
566				case DEFAULT -> buildDefaultToString();
567				case SYSTEM_ENVIRONMENT -> buildSimpleToString('_', (i) -> getElement(i, Form.UNIFORM));
568				case LEGACY_SYSTEM_ENVIRONMENT ->
569					buildSimpleToString('_', (i) -> getElement(i, Form.ORIGINAL).replace('-', '_'));
570			};
571		}
572	
573		private String buildDefaultToString() {
574			if (this.elements.canShortcutWithSource(ElementType.UNIFORM, ElementType.DASHED)) {
575				return this.elements.getSource().toString();
576			}
577			int elements = getNumberOfElements();
578			StringBuilder result = new StringBuilder(elements * 8);
579			for (int i = 0; i < elements; i++) {
580				boolean indexed = isIndexed(i);
581				if (!result.isEmpty() && !indexed) {
582					result.append('.');
583				}
584				if (indexed) {
585					result.append('[');
586					result.append(getElement(i, Form.ORIGINAL));
587					result.append(']');
588				}
589				else {
590					result.append(getElement(i, Form.DASHED));
591				}
592			}
593			return result.toString();
594		}
595	
596		private String buildSimpleToString(char joinChar, IntFunction<String> elementConverter) {
597			StringBuilder result = new StringBuilder();
598			for (int i = 0; i < getNumberOfElements(); i++) {
599				if (!result.isEmpty()) {
600					result.append(joinChar);
601				}
602				result.append(elementConverter.apply(i));
603			}
604			return result.toString();
605		}
606	
607		boolean hasDashedElement() {
608			Boolean hasDashedElement = this.hasDashedElement;
609			if (hasDashedElement != null) {
610				return hasDashedElement;
611			}
612			for (int i = 0; i < getNumberOfElements(); i++) {
613				if (getElement(i, Form.DASHED).indexOf('-') != -1) {
614					this.hasDashedElement = true;
615					return true;
616				}
617			}
618			this.hasDashedElement = false;
619			return false;
620		}
621	
622		/**
623		 * Returns if the given name is valid. If this method returns {@code true} then the
624		 * name may be used with {@link #of(CharSequence)} without throwing an exception.
625		 * @param name the name to test
626		 * @return {@code true} if the name is valid
627		 */
628		public static boolean isValid(@Nullable CharSequence name) {
629			return of(name, true) != null;
630		}
631	
632		/**
633		 * Return a {@link ConfigurationPropertyName} for the specified string.
634		 * @param name the source name
635		 * @return a {@link ConfigurationPropertyName} instance
636		 * @throws InvalidConfigurationPropertyNameException if the name is not valid
637		 */
638		@SuppressWarnings("NullAway") // See https://github.com/uber/NullAway/issues/1232
639		public static ConfigurationPropertyName of(@Nullable CharSequence name) {
640			return of(name, false);
641		}
642	
643		/**
644		 * Return a {@link ConfigurationPropertyName} for the specified string or {@code null}
645		 * if the name is not valid.
646		 * @param name the source name
647		 * @return a {@link ConfigurationPropertyName} instance
648		 * @since 2.3.1
649		 */
650		public static @Nullable ConfigurationPropertyName ofIfValid(@Nullable CharSequence name) {
651			return of(name, true);
652		}
653	
654		/**
655		 * Return a {@link ConfigurationPropertyName} for the specified string.
656		 * @param name the source name
657		 * @param returnNullIfInvalid if null should be returned if the name is not valid
658		 * @return a {@link ConfigurationPropertyName} instance
659		 * @throws InvalidConfigurationPropertyNameException if the name is not valid and
660		 * {@code returnNullIfInvalid} is {@code false}
661		 */
662		@Contract("_, false -> !null")
663		static @Nullable ConfigurationPropertyName of(@Nullable CharSequence name, boolean returnNullIfInvalid) {
664			Elements elements = elementsOf(name, returnNullIfInvalid, ElementsParser.DEFAULT_CAPACITY);
665			return (elements != null) ? new ConfigurationPropertyName(elements) : null;
