673		@Contract("_, false, _ -> !null")
674		private static @Nullable Elements elementsOf(@Nullable CharSequence name, boolean returnNullIfInvalid,
675				int parserCapacity) {
676			if (name == null) {
677				Assert.isTrue(returnNullIfInvalid, "'name' must not be null");
678				return null;
679			}
680			if (name.isEmpty()) {
681				return Elements.EMPTY;
682			}
683			if (name.charAt(0) == '.' || name.charAt(name.length() - 1) == '.') {
684				if (returnNullIfInvalid) {
685					return null;
686				}
687				throw new InvalidConfigurationPropertyNameException(name, Collections.singletonList('.'));
688			}
689			Elements elements = new ElementsParser(name, '.', parserCapacity).parse();
690			for (int i = 0; i < elements.getSize(); i++) {
691				if (elements.getType(i) == ElementType.NON_UNIFORM) {
692					if (returnNullIfInvalid) {
693						return null;
694					}
695					throw new InvalidConfigurationPropertyNameException(name, getInvalidChars(elements, i));
696				}
697			}
698			return elements;
699		}
