701		private static List<Character> getInvalidChars(Elements elements, int index) {
702			List<Character> invalidChars = new ArrayList<>();
703			for (int charIndex = 0; charIndex < elements.getLength(index); charIndex++) {
704				char ch = elements.charAt(index, charIndex);
705				if (!ElementsParser.isValidChar(ch, charIndex)) {
706					invalidChars.add(ch);
707				}
708			}
709			return invalidChars;
710		}
