792		/**
793		 * Allows access to the individual elements that make up the name. We store the
794		 * indexes in arrays rather than a list of object in order to conserve memory.
795		 */
796		private static class Elements {
797	
798			private static final int[] NO_POSITION = {};
799	
800			private static final ElementType[] NO_TYPE = {};
801	
802			public static final Elements EMPTY = new Elements("", 0, NO_POSITION, NO_POSITION, NO_TYPE, null, null);
803	
804			private final CharSequence source;
805	
806			private final int size;
807	
808			private final int[] start;
809	
810			private final int[] end;
811	
812			private final ElementType[] type;
813	
814			private final int[] hashCode;
815	
816			/**
817			 * Contains any resolved elements or can be {@code null} if there aren't any.
818			 * Resolved elements allow us to modify the element values in some way (or example
819			 * when adapting with a mapping function, or when append has been called). Note
820			 * that this array is not used as a cache, in fact, when it's not null then
821			 * {@link #canShortcutWithSource} will always return false which may hurt
822			 * performance.
823			 */
824			private final @Nullable CharSequence @Nullable [] resolved;
825	
826			Elements(CharSequence source, int size, int[] start, int[] end, ElementType[] type, int @Nullable [] hashCode,
827					CharSequence @Nullable [] resolved) {
828				this.source = source;
829				this.size = size;
830				this.start = start;
831				this.end = end;
832				this.type = type;
833				this.hashCode = (hashCode != null) ? hashCode : new int[size];
834				this.resolved = resolved;
835			}
836	
837			Elements append(Elements additional) {
838				int size = this.size + additional.size;
839				ElementType[] type = new ElementType[size];
840				int[] hashCode = new int[size];
841				System.arraycopy(this.type, 0, type, 0, this.size);
842				System.arraycopy(additional.type, 0, type, this.size, additional.size);
843				System.arraycopy(this.hashCode, 0, hashCode, 0, this.size);
844				System.arraycopy(additional.hashCode, 0, hashCode, this.size, additional.size);
845				CharSequence[] resolved = newResolved(0, size);
846				for (int i = 0; i < additional.size; i++) {
847					resolved[this.size + i] = additional.get(i);
848				}
849				return new Elements(this.source, size, this.start, this.end, type, hashCode, resolved);
850			}
851	
852			Elements chop(int size) {
853				CharSequence[] resolved = newResolved(0, size);
854				return new Elements(this.source, size, this.start, this.end, this.type, this.hashCode, resolved);
855			}
856	
857			Elements subElements(int offset) {
858				int size = this.size - offset;
859				CharSequence[] resolved = newResolved(offset, size);
860				int[] start = new int[size];
861				System.arraycopy(this.start, offset, start, 0, size);
862				int[] end = new int[size];
863				System.arraycopy(this.end, offset, end, 0, size);
864				ElementType[] type = new ElementType[size];
865				System.arraycopy(this.type, offset, type, 0, size);
866				int[] hashCode = new int[size];
867				System.arraycopy(this.hashCode, offset, hashCode, 0, size);
868				return new Elements(this.source, size, start, end, type, hashCode, resolved);
869			}
870	
871			private CharSequence[] newResolved(int offset, int size) {
872				CharSequence[] resolved = new CharSequence[size];
873				if (this.resolved != null) {
874					System.arraycopy(this.resolved, offset, resolved, 0, Math.min(size, this.size));
875				}
876				return resolved;
877			}
878	
879			int getSize() {
880				return this.size;
881			}
882	
883			CharSequence get(int index) {
884				if (this.resolved != null) {
885					CharSequence element = this.resolved[index];
886					if (element != null) {
887						return element;
888					}
889				}
890				int start = this.start[index];
891				int end = this.end[index];
892				return this.source.subSequence(start, end);
893			}
894	
895			int getLength(int index) {
896				if (this.resolved != null) {
897					CharSequence element = this.resolved[index];
898					if (element != null) {
899						return element.length();
900					}
901				}
902				int start = this.start[index];
903				int end = this.end[index];
904				return end - start;
905			}
906	
907			char charAt(int index, int charIndex) {
908				if (this.resolved != null) {
909					CharSequence element = this.resolved[index];
910					if (element != null) {
911						return element.charAt(charIndex);
912					}
913				}
914				int start = this.start[index];
915				return this.source.charAt(start + charIndex);
916			}
917	
918			ElementType getType(int index) {
919				return this.type[index];
920			}
921	
922			int hashCode(int index) {
923				int hashCode = this.hashCode[index];
924				if (hashCode == 0) {
925					boolean indexed = getType(index).isIndexed();
926					int length = getLength(index);
927					for (int i = 0; i < length; i++) {
928						char ch = charAt(index, i);
929						if (!indexed) {
930							ch = Character.toLowerCase(ch);
931						}
932						if (ElementsParser.isAlphaNumeric(ch)) {
933							hashCode = 31 * hashCode + ch;
934						}
935					}
936					this.hashCode[index] = hashCode;
937				}
938				return hashCode;
939			}
940	
941			CharSequence getSource() {
942				return this.source;
943			}
