945			/**
946			 * Returns if the element source can be used as a shortcut for an operation such
947			 * as {@code equals} or {@code toString}.
948			 * @param requiredType the required type
949			 * @return {@code true} if all elements match at least one of the types
950			 */
951			boolean canShortcutWithSource(ElementType requiredType) {
952				return canShortcutWithSource(requiredType, requiredType);
953			}
954	
955			/**
956			 * Returns if the element source can be used as a shortcut for an operation such
957			 * as {@code equals} or {@code toString}.
958			 * @param requiredType the required type
959			 * @param alternativeType and alternative required type
960			 * @return {@code true} if all elements match at least one of the types
961			 */
962			boolean canShortcutWithSource(ElementType requiredType, ElementType alternativeType) {
963				if (this.resolved != null) {
964					return false;
965				}
966				for (int i = 0; i < this.size; i++) {
967					ElementType type = this.type[i];
968					if (type != requiredType && type != alternativeType) {
969						return false;
970					}
971					if (i > 0 && this.end[i - 1] + 1 != this.start[i]) {
972						return false;
973					}
974				}
975				return true;
976			}
