980		/**
981		 * Main parsing logic used to convert a {@link CharSequence} to {@link Elements}.
982		 */
983		private static class ElementsParser {
984	
985			private static final int DEFAULT_CAPACITY = 6;
986	
987			private final CharSequence source;
988	
989			private final char separator;
990	
991			private int size;
992	
993			private int[] start;
994	
995			private int[] end;
996	
997			private ElementType[] type;
998	
999			private CharSequence @Nullable [] resolved;
1000	
1001			ElementsParser(CharSequence source, char separator) {
1002				this(source, separator, DEFAULT_CAPACITY);
1003			}
1004	
1005			ElementsParser(CharSequence source, char separator, int capacity) {
1006				this.source = source;
1007				this.separator = separator;
1008				this.start = new int[capacity];
1009				this.end = new int[capacity];
1010				this.type = new ElementType[capacity];
1011			}
1012	
1013			Elements parse() {
1014				return parse(null);
1015			}
1016	
1017			Elements parse(@Nullable Function<CharSequence, CharSequence> valueProcessor) {
1018				int length = this.source.length();
1019				int openBracketCount = 0;
1020				int start = 0;
1021				ElementType type = ElementType.EMPTY;
1022				for (int i = 0; i < length; i++) {
1023					char ch = this.source.charAt(i);
1024					if (ch == '[') {
1025						if (openBracketCount == 0) {
1026							add(start, i, type, valueProcessor);
1027							start = i + 1;
1028							type = ElementType.NUMERICALLY_INDEXED;
1029						}
1030						openBracketCount++;
1031					}
1032					else if (ch == ']') {
1033						openBracketCount--;
1034						if (openBracketCount == 0) {
1035							add(start, i, type, valueProcessor);
1036							start = i + 1;
1037							type = ElementType.EMPTY;
1038						}
1039					}
1040					else if (!type.isIndexed() && ch == this.separator) {
1041						add(start, i, type, valueProcessor);
1042						start = i + 1;
1043						type = ElementType.EMPTY;
1044					}
1045					else {
1046						type = updateType(type, ch, i - start);
1047					}
1048				}
1049				if (openBracketCount != 0) {
1050					type = ElementType.NON_UNIFORM;
1051				}
1052				add(start, length, type, valueProcessor);
1053				return new Elements(this.source, this.size, this.start, this.end, this.type, null, this.resolved);
1054			}
1055	
1056			private ElementType updateType(ElementType existingType, char ch, int index) {
1057				if (existingType.isIndexed()) {
1058					if (existingType == ElementType.NUMERICALLY_INDEXED && !isNumeric(ch)) {
1059						return ElementType.INDEXED;
1060					}
1061					return existingType;
1062				}
1063				if (existingType == ElementType.EMPTY && isValidChar(ch, index)) {
1064					return (index == 0) ? ElementType.UNIFORM : ElementType.NON_UNIFORM;
1065				}
1066				if (existingType == ElementType.UNIFORM && ch == '-') {
1067					return ElementType.DASHED;
1068				}
1069				if (!isValidChar(ch, index)) {
1070					if (existingType == ElementType.EMPTY && !isValidChar(Character.toLowerCase(ch), index)) {
1071						return ElementType.EMPTY;
1072					}
1073					return ElementType.NON_UNIFORM;
1074				}
1075				return existingType;
1076			}
1077	
1078			private void add(int start, int end, ElementType type,
1079					@Nullable Function<CharSequence, CharSequence> valueProcessor) {
1080				if ((end - start) < 1 || type == ElementType.EMPTY) {
1081					return;
1082				}
1083				if (this.start.length == this.size) {
1084					this.start = expand(this.start);
1085					this.end = expand(this.end);
1086					this.type = expand(this.type);
1087					this.resolved = expand(this.resolved);
1088				}
1089				if (valueProcessor != null) {
1090					if (this.resolved == null) {
1091						this.resolved = new CharSequence[this.start.length];
1092					}
1093					CharSequence resolved = valueProcessor.apply(this.source.subSequence(start, end));
1094					Elements resolvedElements = new ElementsParser(resolved, '.').parse();
1095					Assert.state(resolvedElements.getSize() == 1, "Resolved element must not contain multiple elements");
1096					this.resolved[this.size] = resolvedElements.get(0);
1097					type = resolvedElements.getType(0);
1098				}
1099				this.start[this.size] = start;
1100				this.end[this.size] = end;
1101				this.type[this.size] = type;
1102				this.size++;
1103			}
1104	
1105			private int[] expand(int[] src) {
1106				int[] dest = new int[src.length + DEFAULT_CAPACITY];
1107				System.arraycopy(src, 0, dest, 0, src.length);
1108				return dest;
1109			}
1110	
1111			private ElementType[] expand(ElementType[] src) {
1112				ElementType[] dest = new ElementType[src.length + DEFAULT_CAPACITY];
1113				System.arraycopy(src, 0, dest, 0, src.length);
1114				return dest;
1115			}
1116	
1117			private CharSequence @Nullable [] expand(CharSequence @Nullable [] src) {
1118				if (src == null) {
1119					return null;
1120				}
1121				CharSequence[] dest = new CharSequence[src.length + DEFAULT_CAPACITY];
1122				System.arraycopy(src, 0, dest, 0, src.length);
1123				return dest;
1124			}
1125	
1126			static boolean isValidChar(char ch, int index) {
1127				return isAlpha(ch) || isNumeric(ch) || (index != 0 && ch == '-');
1128			}
1129	
1130			static boolean isAlphaNumeric(char ch) {
1131				return isAlpha(ch) || isNumeric(ch);
1132			}
1133	
1134			private static boolean isAlpha(char ch) {
1135				return ch >= 'a' && ch <= 'z';
1136			}
1137	
1138			private static boolean isNumeric(char ch) {
1139				return ch >= '0' && ch <= '9';
1140			}
1141	
1142		}
