17	package org.springframework.boot.context.properties;
18	
19	import java.lang.annotation.Annotation;
20	import java.lang.reflect.AnnotatedElement;
21	import java.lang.reflect.Constructor;
22	import java.lang.reflect.Method;
23	import java.util.Iterator;
24	import java.util.LinkedHashMap;
25	import java.util.Map;
26	
27	import org.jspecify.annotations.Nullable;
28	
29	import org.springframework.aop.support.AopUtils;
30	import org.springframework.beans.factory.NoSuchBeanDefinitionException;
31	import org.springframework.beans.factory.config.BeanDefinition;
32	import org.springframework.beans.factory.config.BeanPostProcessor;
33	import org.springframework.beans.factory.config.ConfigurableListableBeanFactory;
34	import org.springframework.beans.factory.support.RootBeanDefinition;
35	import org.springframework.boot.context.properties.bind.BindConstructorProvider;
36	import org.springframework.boot.context.properties.bind.BindMethod;
37	import org.springframework.boot.context.properties.bind.Bindable;
38	import org.springframework.boot.context.properties.bind.Binder;
39	import org.springframework.context.ApplicationContext;
40	import org.springframework.context.ConfigurableApplicationContext;
41	import org.springframework.context.annotation.Bean;
42	import org.springframework.core.ResolvableType;
43	import org.springframework.core.annotation.MergedAnnotation;
44	import org.springframework.core.annotation.MergedAnnotations;
45	import org.springframework.core.annotation.MergedAnnotations.SearchStrategy;
46	import org.springframework.lang.Contract;
47	import org.springframework.util.Assert;
48	import org.springframework.validation.annotation.Validated;
49	
50	/**
51	 * Provides access to {@link ConfigurationProperties @ConfigurationProperties} bean
52	 * details, regardless of if the annotation was used directly or on a {@link Bean @Bean}
53	 * factory method. This class can be used to access {@link #getAll(ApplicationContext)
54	 * all} configuration properties beans in an ApplicationContext, or
55	 * {@link #get(ApplicationContext, Object, String) individual beans} on a case-by-case
56	 * basis (for example, in a {@link BeanPostProcessor}).
57	 *
58	 * @author Phillip Webb
59	 * @since 2.2.0
60	 * @see #getAll(ApplicationContext)
61	 * @see #get(ApplicationContext, Object, String)
62	 */
63	public final class ConfigurationPropertiesBean {
64	
65		private final String name;
66	
67		private final @Nullable Object instance;
68	
69		private final Bindable<?> bindTarget;
70	
71		private ConfigurationPropertiesBean(String name, @Nullable Object instance, Bindable<?> bindTarget) {
72			this.name = name;
73			this.instance = instance;
74			this.bindTarget = bindTarget;
75		}
76	
77		/**
78		 * Return the name of the Spring bean.
79		 * @return the bean name
80		 */
81		public String getName() {
82			return this.name;
83		}
84	
85		/**
86		 * Return the actual Spring bean instance.
87		 * @return the bean instance
88		 */
89		public @Nullable Object getInstance() {
90			return this.instance;
91		}
92	
93		/**
94		 * Return the bean type.
95		 * @return the bean type
96		 */
97		Class<?> getType() {
98			Class<?> resolved = this.bindTarget.getType().resolve();
99			Assert.state(resolved != null, "'resolved' must not be null");
100			return resolved;
101		}
102	
103		/**
104		 * Return the {@link ConfigurationProperties} annotation for the bean. The annotation
105		 * may be defined on the bean itself or from the factory method that create the bean
106		 * (usually a {@link Bean @Bean} method).
107		 * @return the configuration properties annotation
108		 */
109		public ConfigurationProperties getAnnotation() {
110			ConfigurationProperties annotation = this.bindTarget.getAnnotation(ConfigurationProperties.class);
111			Assert.state(annotation != null, "'annotation' must not be null");
112			return annotation;
113		}
114	
115		/**
116		 * Return a {@link Bindable} instance suitable that can be used as a target for the
117		 * {@link Binder}.
118		 * @return a bind target for use with the {@link Binder}
119		 */
120		public Bindable<?> asBindTarget() {
121			return this.bindTarget;
122		}
123	
124		/**
125		 * Return all {@link ConfigurationProperties @ConfigurationProperties} beans contained
126		 * in the given application context. Both directly annotated beans, as well as beans
127		 * that have {@link ConfigurationProperties @ConfigurationProperties} annotated
128		 * factory methods are included.
129		 * @param applicationContext the source application context
130		 * @return a map of all configuration properties beans keyed by the bean name
131		 */
132		public static Map<String, ConfigurationPropertiesBean> getAll(ApplicationContext applicationContext) {
133			Assert.notNull(applicationContext, "'applicationContext' must not be null");
134			if (applicationContext instanceof ConfigurableApplicationContext configurableContext) {
135				return getAll(configurableContext);
136			}
137			Map<String, ConfigurationPropertiesBean> propertiesBeans = new LinkedHashMap<>();
138			applicationContext.getBeansWithAnnotation(ConfigurationProperties.class).forEach((name, instance) -> {
139				ConfigurationPropertiesBean propertiesBean = get(applicationContext, instance, name);
140				if (propertiesBean != null) {
141					propertiesBeans.put(name, propertiesBean);
142				}
143			});
144			return propertiesBeans;
145		}
146	
147		private static Map<String, ConfigurationPropertiesBean> getAll(ConfigurableApplicationContext applicationContext) {
148			Map<String, ConfigurationPropertiesBean> propertiesBeans = new LinkedHashMap<>();
149			ConfigurableListableBeanFactory beanFactory = applicationContext.getBeanFactory();
150			Iterator<String> beanNames = beanFactory.getBeanNamesIterator();
151			while (beanNames.hasNext()) {
152				String beanName = beanNames.next();
153				if (isConfigurationPropertiesBean(beanFactory, beanName)) {
154					try {
155						Object bean = beanFactory.getBean(beanName);
156						ConfigurationPropertiesBean propertiesBean = get(applicationContext, bean, beanName);
157						if (propertiesBean != null) {
158							propertiesBeans.put(beanName, propertiesBean);
159						}
160					}
161					catch (Exception ex) {
162						// Ignore
163					}
164				}
165			}
166			return propertiesBeans;
167		}
168	
169		private static boolean isConfigurationPropertiesBean(ConfigurableListableBeanFactory beanFactory, String beanName) {
170			try {
171				if (beanFactory.getBeanDefinition(beanName).isAbstract()) {
172					return false;
173				}
174				if (beanFactory.findAnnotationOnBean(beanName, ConfigurationProperties.class) != null) {
175					return true;
176				}
177				Method factoryMethod = findFactoryMethod(beanFactory, beanName);
178				return findMergedAnnotation(factoryMethod, ConfigurationProperties.class).isPresent();
179			}
180			catch (NoSuchBeanDefinitionException ex) {
181				return false;
182			}
183		}
184	
185		/**
186		 * Return a {@link ConfigurationPropertiesBean @ConfigurationPropertiesBean} instance
187		 * for the given bean details or {@code null} if the bean is not a
188		 * {@link ConfigurationProperties @ConfigurationProperties} object. Annotations are
189		 * considered both on the bean itself, as well as any factory method (for example a
190		 * {@link Bean @Bean} method).
191		 * @param applicationContext the source application context
192		 * @param bean the bean to consider
193		 * @param beanName the bean name
194		 * @return a configuration properties bean or {@code null} if the neither the bean nor
195		 * factory method are annotated with
196		 * {@link ConfigurationProperties @ConfigurationProperties}
197		 */
198		public static @Nullable ConfigurationPropertiesBean get(ApplicationContext applicationContext, Object bean,
199				String beanName) {
200			Method factoryMethod = findFactoryMethod(applicationContext, beanName);
201			Bindable<Object> bindTarget = createBindTarget(bean, bean.getClass(), factoryMethod);
202			if (bindTarget == null) {
203				return null;
204			}
205			bindTarget = bindTarget.withBindMethod(BindMethodAttribute.get(applicationContext, beanName));
206			if (bindTarget.getBindMethod() == null && factoryMethod != null) {
207				bindTarget = bindTarget.withBindMethod(BindMethod.JAVA_BEAN);
208			}
209			if (bindTarget.getBindMethod() != BindMethod.VALUE_OBJECT) {
210				bindTarget = bindTarget.withExistingValue(bean);
211			}
212			return create(beanName, bean, bindTarget);
213		}
214	
215		private static @Nullable Method findFactoryMethod(ApplicationContext applicationContext, String beanName) {
216			if (applicationContext instanceof ConfigurableApplicationContext configurableContext) {
217				return findFactoryMethod(configurableContext, beanName);
218			}
219			return null;
220		}
221	
222		private static @Nullable Method findFactoryMethod(ConfigurableApplicationContext applicationContext,
223				String beanName) {
224			return findFactoryMethod(applicationContext.getBeanFactory(), beanName);
225		}
226	
227		private static @Nullable Method findFactoryMethod(ConfigurableListableBeanFactory beanFactory, String beanName) {
228			if (beanFactory.containsBeanDefinition(beanName)) {
229				BeanDefinition beanDefinition = beanFactory.getMergedBeanDefinition(beanName);
230				if (beanDefinition instanceof RootBeanDefinition rootBeanDefinition) {
231					return rootBeanDefinition.getResolvedFactoryMethod();
232				}
233			}
234			return null;
235		}
236	
237		static ConfigurationPropertiesBean forValueObject(Class<?> beanType, String beanName) {
238			Bindable<Object> bindTarget = createBindTarget(null, beanType, null);
239			Assert.state(bindTarget != null && deduceBindMethod(bindTarget) == BindMethod.VALUE_OBJECT,
240					() -> "Bean '" + beanName + "' is not a @ConfigurationProperties value object");
241			return create(beanName, null, bindTarget.withBindMethod(BindMethod.VALUE_OBJECT));
242		}
243	
244		private static @Nullable Bindable<Object> createBindTarget(@Nullable Object bean, Class<?> beanType,
245				@Nullable Method factoryMethod) {
246			ResolvableType type = (factoryMethod != null) ? ResolvableType.forMethodReturnType(factoryMethod)
247					: ResolvableType.forClass(beanType);
248			Annotation[] annotations = findAnnotations(bean, beanType, factoryMethod);
249			return (annotations != null) ? Bindable.of(type).withAnnotations(annotations) : null;
250		}
251	
252		private static Annotation @Nullable [] findAnnotations(@Nullable Object instance, Class<?> type,
253				@Nullable Method factory) {
254			ConfigurationProperties annotation = findAnnotation(instance, type, factory, ConfigurationProperties.class);
255			if (annotation == null) {
256				return null;
257			}
258			Validated validated = findAnnotation(instance, type, factory, Validated.class);
259			return (validated != null) ? new Annotation[] { annotation, validated } : new Annotation[] { annotation };
260		}
261	
262		private static <A extends Annotation> @Nullable A findAnnotation(@Nullable Object instance, Class<?> type,
263				@Nullable Method factory, Class<A> annotationType) {
264			MergedAnnotation<A> annotation = MergedAnnotation.missing();
265			if (factory != null) {
266				annotation = findMergedAnnotation(factory, annotationType);
267			}
268			if (!annotation.isPresent()) {
269				annotation = findMergedAnnotation(type, annotationType);
270			}
271			if (!annotation.isPresent() && AopUtils.isAopProxy(instance)) {
272				annotation = MergedAnnotations.from(AopUtils.getTargetClass(instance), SearchStrategy.TYPE_HIERARCHY)
273					.get(annotationType);
274			}
275			return annotation.isPresent() ? annotation.synthesize() : null;
276		}
277	
278		private static <A extends Annotation> MergedAnnotation<A> findMergedAnnotation(@Nullable AnnotatedElement element,
279				Class<A> annotationType) {
280			return (element != null) ? MergedAnnotations.from(element, SearchStrategy.TYPE_HIERARCHY).get(annotationType)
281					: MergedAnnotation.missing();
282		}
283	
284		@Contract("_, _, !null -> !null")
285		private static @Nullable ConfigurationPropertiesBean create(String name, @Nullable Object instance,
286				@Nullable Bindable<Object> bindTarget) {
287			return (bindTarget != null) ? new ConfigurationPropertiesBean(name, instance, bindTarget) : null;
288		}
289	
290		/**
291		 * Deduce the {@code BindMethod} that should be used for the given type.
292		 * @param type the source type
293		 * @return the bind method to use
294		 */
295		static BindMethod deduceBindMethod(Class<?> type) {
296			return deduceBindMethod(BindConstructorProvider.DEFAULT.getBindConstructor(type, false));
297		}
298	
299		/**
300		 * Deduce the {@code BindMethod} that should be used for the given {@link Bindable}.
301		 * @param bindable the source bindable
302		 * @return the bind method to use
303		 */
304		static BindMethod deduceBindMethod(Bindable<Object> bindable) {
305			return deduceBindMethod(BindConstructorProvider.DEFAULT.getBindConstructor(bindable, false));
306		}
307	
308		private static BindMethod deduceBindMethod(@Nullable Constructor<?> bindConstructor) {
309			return (bindConstructor != null) ? BindMethod.VALUE_OBJECT : BindMethod.JAVA_BEAN;
310		}
311	
312	}
