17	package org.springframework.boot.diagnostics.analyzer;
18	
19	import java.util.ArrayList;
20	import java.util.List;
21	import java.util.Objects;
22	
23	import org.jspecify.annotations.Nullable;
24	
25	import org.springframework.beans.factory.BeanCreationException;
26	import org.springframework.beans.factory.BeanCurrentlyInCreationException;
27	import org.springframework.beans.factory.BeanFactory;
28	import org.springframework.beans.factory.InjectionPoint;
29	import org.springframework.beans.factory.UnsatisfiedDependencyException;
30	import org.springframework.beans.factory.support.AbstractAutowireCapableBeanFactory;
31	import org.springframework.boot.diagnostics.AbstractFailureAnalyzer;
32	import org.springframework.boot.diagnostics.FailureAnalysis;
33	import org.springframework.util.StringUtils;
34	
35	/**
36	 * An {@link AbstractFailureAnalyzer} that performs analysis of failures caused by a
37	 * {@link BeanCurrentlyInCreationException}.
38	 *
39	 * @author Andy Wilkinson
40	 * @author Scott Frederick
41	 */
42	class BeanCurrentlyInCreationFailureAnalyzer extends AbstractFailureAnalyzer<BeanCurrentlyInCreationException> {
43	
44		private final @Nullable AbstractAutowireCapableBeanFactory beanFactory;
45	
46		BeanCurrentlyInCreationFailureAnalyzer(BeanFactory beanFactory) {
47			if (beanFactory instanceof AbstractAutowireCapableBeanFactory autowireCapableBeanFactory) {
48				this.beanFactory = autowireCapableBeanFactory;
49			}
50			else {
51				this.beanFactory = null;
52			}
53		}
54	
55		@Override
56		protected @Nullable FailureAnalysis analyze(Throwable rootFailure, BeanCurrentlyInCreationException cause) {
57			DependencyCycle dependencyCycle = findCycle(rootFailure);
58			if (dependencyCycle == null) {
59				return null;
60			}
61			return new FailureAnalysis(buildMessage(dependencyCycle), action(), cause);
62		}
63	
64		private String action() {
65			if (this.beanFactory != null && this.beanFactory.isAllowCircularReferences()) {
66				return "Despite circular references being allowed, the dependency cycle between beans could not be "
67						+ "broken. Update your application to remove the dependency cycle.";
68			}
69			return "Relying upon circular references is discouraged and they are prohibited by default. "
70					+ "Update your application to remove the dependency cycle between beans. "
71					+ "As a last resort, it may be possible to break the cycle automatically by setting "
72					+ "spring.main.allow-circular-references to true.";
73		}
74	
75		private @Nullable DependencyCycle findCycle(Throwable rootFailure) {
76			List<BeanInCycle> beansInCycle = new ArrayList<>();
77			Throwable candidate = rootFailure;
78			int cycleStart = -1;
79			while (candidate != null) {
80				BeanInCycle beanInCycle = BeanInCycle.get(candidate);
81				if (beanInCycle != null) {
82					int index = beansInCycle.indexOf(beanInCycle);
83					if (index == -1) {
84						beansInCycle.add(beanInCycle);
85					}
86					cycleStart = (cycleStart != -1) ? cycleStart : index;
87				}
88				candidate = candidate.getCause();
89			}
90			if (cycleStart == -1) {
91				return null;
92			}
93			return new DependencyCycle(beansInCycle, cycleStart);
94		}
95	
96		private String buildMessage(DependencyCycle dependencyCycle) {
97			StringBuilder message = new StringBuilder();
98			message.append(
99					String.format("The dependencies of some of the beans in the application context form a cycle:%n%n"));
100			List<BeanInCycle> beansInCycle = dependencyCycle.getBeansInCycle();
101			boolean singleBean = beansInCycle.size() == 1;
102			int cycleStart = dependencyCycle.getCycleStart();
103			for (int i = 0; i < beansInCycle.size(); i++) {
104				BeanInCycle beanInCycle = beansInCycle.get(i);
105				if (i == cycleStart) {
106					message.append(String.format(singleBean ? "┌──->──┐%n" : "┌─────┐%n"));
107				}
108				else if (i > 0) {
109					String leftSide = (i < cycleStart) ? " " : "↑";
110					message.append(String.format("%s     ↓%n", leftSide));
111				}
112				String leftSide = (i < cycleStart) ? " " : "|";
113				message.append(String.format("%s  %s%n", leftSide, beanInCycle));
114			}
115			message.append(String.format(singleBean ? "└──<-──┘%n" : "└─────┘%n"));
116			return message.toString();
117		}
118	
119		private static final class DependencyCycle {
120	
121			private final List<BeanInCycle> beansInCycle;
122	
123			private final int cycleStart;
124	
125			private DependencyCycle(List<BeanInCycle> beansInCycle, int cycleStart) {
126				this.beansInCycle = beansInCycle;
127				this.cycleStart = cycleStart;
128			}
129	
130			List<BeanInCycle> getBeansInCycle() {
131				return this.beansInCycle;
132			}
133	
134			int getCycleStart() {
135				return this.cycleStart;
136			}
137	
138		}
139	
140		private static final class BeanInCycle {
141	
142			private final @Nullable String name;
143	
144			private final String description;
145	
146			private BeanInCycle(BeanCreationException ex) {
147				this.name = ex.getBeanName();
148				this.description = determineDescription(ex);
149			}
150	
151			private String determineDescription(BeanCreationException ex) {
152				if (StringUtils.hasText(ex.getResourceDescription())) {
153					return String.format(" defined in %s", ex.getResourceDescription());
154				}
155				InjectionPoint failedInjectionPoint = findFailedInjectionPoint(ex);
156				if (failedInjectionPoint != null && failedInjectionPoint.getField() != null) {
157					return String.format(" (field %s)", failedInjectionPoint.getField());
158				}
159				return "";
160			}
161	
162			private @Nullable InjectionPoint findFailedInjectionPoint(BeanCreationException ex) {
163				if (ex instanceof UnsatisfiedDependencyException unsatisfiedDependencyException) {
